<template><div class="folder-list"><div class="list-head"><span class="name-head">Name <span class="sort">↑</span></span><span>Type</span><span>Modified</span><span></span></div><FileItem v-for="folder in library.visibleFolders.value" :key="folder.id" :icon="folder.icon" :name="folder.name" type="Folder" :selected="library.selectedFolder.value?.id===folder.id" :modified="formatModified(folder.modified_at)" @click="library.selectFolder(folder)" @open="library.openFolder(folder.id)"/><div v-if="library.visibleFolders.value.length===0" class="empty">No folders yet.</div></div></template>
<script setup lang="ts">import FileItem from "./FileItem.vue";import {useLibrary} from "../stores/library";const library=useLibrary();function formatModified(value?:string|null){if(!value)return "—";const date=new Date(value);return Number.isNaN(date.getTime())?"—":date.toISOString().slice(0,16).replace("T"," ")}</script>
<style scoped>
.folder-list{flex:1;min-height:0;overflow:auto;background:var(--content-bg)}.list-head{min-height:42px;display:grid;grid-template-columns:48px minmax(180px,1fr) minmax(90px,18%) minmax(150px,18%) 38px;align-items:center;gap:8px;padding:0 22px;background:linear-gradient(180deg,var(--header-bg-1),var(--header-bg-2));border-bottom:1px solid var(--border);color:var(--text-2);font-size:13px;font-weight:700;position:sticky;top:0;z-index:2}.list-head .name-head{grid-column:1/3}.sort{margin-left:4px;color:var(--accent-strong)}.empty{display:flex;justify-content:center;align-items:center;height:calc(100% - 42px);min-height:180px;color:var(--text-3);font-size:15px}@media(max-width:760px){.list-head{grid-template-columns:42px minmax(150px,1fr) 80px 34px;padding:0 12px}.list-head .name-head{grid-column:1/3}.list-head span:nth-child(3){display:none}}
</style>